const referenceCharacters=[
 {name:'男生 · 耳机街头',frame:[40,5,350,538],outfit:'rose'},
 {name:'男生 · 奶白学院',frame:[412,7,335,535],outfit:'mint'},
 {name:'男生 · 运动外套',frame:[777,5,330,538],outfit:'lilac'},
 {name:'男生 · 软萌兔子',frame:[1160,5,310,537],outfit:'gold'},
 {name:'女生 · 双马尾街头',frame:[17,543,394,481],outfit:'rose'},
 {name:'女生 · 贝雷帽学院',frame:[413,539,335,485],outfit:'mint'},
 {name:'女生 · 高马尾运动',frame:[777,539,330,485],outfit:'lilac'},
 {name:'女生 · 软萌兔子',frame:[1140,540,345,484],outfit:'gold'}
];
function referenceIndex(id,a={}){if(Number.isInteger(a.referenceSprite)&&referenceCharacters[a.referenceSprite])return a.referenceSprite;const gender=a.cut==='suit'||id!=='me'&&roles.findIndex(r=>r.id===id)%2===1?0:4,index=Math.max(0,['rose','mint','lilac','gold'].indexOf(a.outfit));return gender+index}
function chibiAvatar(id='me',draft=null){const a=draft||living.avatars[id]||{},uploaded=!draft&&mediaCache.get('chibi:'+id);if(uploaded)return `<span class="chibi"><img src="${uploaded}" alt="自定义Q版形象"></span>`;const index=referenceIndex(id,a),c=referenceCharacters[index],[x,y,w,h]=c.frame;return `<span class="chibi reference-character ${index>=4?'reference-girl':'reference-boy'}" role="img" aria-label="${c.name}"><svg xmlns="http://www.w3.org/2000/svg" viewBox="${x} ${y} ${w} ${h}" preserveAspectRatio="xMidYMax meet"><defs><clipPath id="referenceClip-${index}" clipPathUnits="userSpaceOnUse"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><g clip-path="url(#referenceClip-${index})"><image href="assets/reference-characters-v14.webp" x="0" y="0" width="1536" height="1024"/></g></svg></span>`}
function openChibiEditor(id='me'){let draft={...living.avatars[id],layered:false,referenceSprite:referenceIndex(id,living.avatars[id])};const draw=()=>{const index=draft.referenceSprite,style=referenceCharacters[index],key=style.outfit,owned=homeland.owned.includes(key),cost=PalaisHome.clothes[key].price;draft.outfit=key;const d=homePanel(`<div class="eyebrow">YOUR REFERENCE WARDROBE</div><h2>${id==='me'?'我的':escapeHtml(roles.find(r=>r.id===id)?.name||'角色')}形象与换装</h2><div class="living-preview" id="chibiLive">${chibiAvatar(id,draft)}</div><p class="daily-caption">参考图中的男女成套形象，点击即预览；用户与每位角色分别保存。当前按完整造型切换，保留上传自定义形象。</p><div class="reference-wardrobe">${referenceCharacters.map((c,i)=>`<button data-reference-character="${i}" aria-pressed="${i===index}" class="${i===index?'selected':''}">${chibiAvatar(id,{referenceSprite:i})}<b>${c.name}</b><small>${homeland.owned.includes(c.outfit)?'已拥有':'¥'+PalaisWallet.money(PalaisHome.clothes[c.outfit].price*100)}</small></button>`).join('')}</div><input type="file" hidden id="chibiUpload" accept="image/png,image/jpeg,image/webp"><p class="daily-caption">零钱 ¥${PalaisWallet.money(wallet.balance)} · ${owned?'当前服装已拥有':'本套服装 ¥'+PalaisWallet.money(cost*100)}。服装只在确认购买时扣款，预览不扣钱。</p><div class="actions"><button class="secondary" id="uploadChibi">上传Q版图</button><button class="primary" id="saveChibi">${owned?'保存形象':'购买并保存 · ¥'+PalaisWallet.money(cost*100)}</button></div>`);d.querySelectorAll('[data-reference-character]').forEach(b=>b.onclick=()=>{draft.referenceSprite=Number(b.dataset.referenceCharacter);draw()});$('#uploadChibi').onclick=()=>$('#chibiUpload').click();$('#chibiUpload').onchange=async e=>{try{const image=await prepareImage(e.target.files[0],1000);await mediaWrite('chibi:'+id,image);d.close();renderHomeland();toast('Q版形象已上传')}catch(err){toast(err.message)}};$('#saveChibi').onclick=async()=>{const button=$('#saveChibi');button.disabled=true;try{const r=PalaisHomeCash.purchaseStyle(wallet,homeland,key,crypto.randomUUID(),Date.now(),PalaisHome.clothes),old=mediaCache.get('chibi:'+id)||null;await mediaWrite('chibi:'+id,null);try{livingCommit(r.wallet,{...living,avatars:{...living.avatars,[id]:draft}},r.home)}catch(e){await mediaWrite('chibi:'+id,old).catch(()=>{});throw e}d.close();renderHomeland();toast('形象已保存')}catch(err){toast(err.message);button.disabled=false}}};draw()}
function migrateHomeCash(){const saved=localRead('chatState',null),hadHome=!!(saved?.homeState||localRead('homeland',null));const r=PalaisHomeCash.migrate(wallet,homeland,hadHome);try{livingCommit(r.wallet,living,r.home);return true}catch(e){toast('家园金钱迁移未保存，未重复兑换：'+e.message);return false}}
